import * as THREE from './vendor/three.module.js';
import {SPECTRUM} from './prismwing-character.js?v=overall-performance-238';
export class PrismwingEffects {
 constructor(scene){this.root=new THREE.Group();this.root.name='Prismwing rainbow magic';scene.add(this.root);this.particles=[];this.bursts=[];this.clock=0;this.dummy=new THREE.Object3D();this.up=new THREE.Vector3(0,1,0);this.colors=SPECTRUM.map(c=>new THREE.Color(c));const material=(opacity=1)=>new THREE.MeshBasicMaterial({color:'#ffffff',transparent:opacity<1,opacity,depthWrite:opacity===1,toneMapped:false});this.beam=new THREE.InstancedMesh(new THREE.CylinderGeometry(1,1,1,5,1,true),material(),112);this.glow=new THREE.InstancedMesh(this.beam.geometry,material(.18),112);this.sparks=new THREE.InstancedMesh(new THREE.IcosahedronGeometry(1,0),material(),192);this.rings=new THREE.InstancedMesh(new THREE.TorusGeometry(1,.045,4,28),material(.8),28);for(const m of[this.beam,this.glow,this.sparks,this.rings]){m.frustumCulled=false;m.count=0;this.root.add(m);}this.reset();}
 reset(){this.particles.length=this.bursts.length=0;this.clock=0;this.emitTimer=0;this.lastCharge=-1;for(const m of[this.beam,this.glow,this.sparks,this.rings])m.count=0;}
 particle(p,i,speed=2){if(this.particles.length>=192)this.particles.shift();const a=i*2.399+this.clock;this.particles.push({p:p.clone(),v:new THREE.Vector3(Math.cos(a)*speed,Math.sin(a*1.3)*speed+1,Math.sin(a)*speed),life:.4+(i%3)*.12,max:.64,color:this.colors[i%7]});}
 impact(point,direction){if(this.bursts.length>=4)this.bursts.shift();this.bursts.push({p:new THREE.Vector3().copy(point),q:new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0,0,1),direction),age:0});for(let i=0;i<21;i++)this.particle(new THREE.Vector3().copy(point),i,5);}
 put(mesh,i,p,scale,color,q=new THREE.Quaternion()){this.dummy.position.copy(p);this.dummy.quaternion.copy(q);this.dummy.scale.copy(scale);this.dummy.updateMatrix();mesh.setMatrixAt(i,this.dummy.matrix);mesh.setColorAt(i,color);}
 update(dt,time,{from=null,end=null,charge=0,contact=false}={}){this.clock+=dt;this.beam.count=this.glow.count=0;if(from&&end){const direction=end.clone().sub(from),length=direction.length(),forward=direction.clone().normalize(),side=new THREE.Vector3().crossVectors(forward,this.up);if(side.lengthSq()<.001)side.set(1,0,0);else side.normalize();const up=new THREE.Vector3().crossVectors(side,forward).normalize();let n=0;for(let color=0;color<7;color++){let previous=from.clone();for(let i=1;i<=16;i++){const t=i/16,p=from.clone().lerp(end,t),width=Math.sin(Math.PI*t)*.3+.035;p.addScaledVector(side,(color-3)*width).addScaledVector(up,Math.sin(t*Math.PI)*.12+Math.sin(t*18-time*12)*.03);if(i===16)p.copy(end);const d=p.clone().sub(previous),q=new THREE.Quaternion().setFromUnitVectors(this.up,d.clone().normalize()),middle=previous.clone().lerp(p,.5),r=.045+.02*Math.sin(time*13+t*5)**2;this.put(this.beam,n,middle,new THREE.Vector3(r,d.length(),r),this.colors[color],q);this.put(this.glow,n,middle,new THREE.Vector3(r*2.8,d.length(),r*2.8),this.colors[color],q);n++;previous=p;}}this.beam.count=this.glow.count=n;this.emitTimer=(this.emitTimer||0)-dt;if(contact&&this.emitTimer<=0){this.impact(end,forward);this.emitTimer=.14;}}else if(charge>0&&from){if(Math.floor(time*30)!==this.lastCharge){for(let i=0;i<2;i++)this.particle(from,i+Math.floor(time*30),.7);this.lastCharge=Math.floor(time*30);}}
  this.rings.count=0;let ring=0;for(let i=this.bursts.length-1;i>=0;i--){const b=this.bursts[i];b.age+=dt;if(b.age>.5){this.bursts.splice(i,1);continue;}for(let c=0;c<7;c++){const r=.15+c*.1+b.age*2;this.put(this.rings,ring++,b.p,new THREE.Vector3(r,r,r),this.colors[c].clone().multiplyScalar(1-b.age*1.5),b.q);}}this.rings.count=ring;
  let n=0;for(let i=this.particles.length-1;i>=0;i--){const p=this.particles[i];p.life-=dt;if(p.life<=0){this.particles.splice(i,1);continue;}p.v.y-=2*dt;p.p.addScaledVector(p.v,dt);this.put(this.sparks,n++,p.p,new THREE.Vector3().setScalar(.055*p.life/p.max),p.color);}this.sparks.count=n;for(const m of[this.beam,this.glow,this.rings,this.sparks]){m.instanceMatrix.needsUpdate=true;if(m.instanceColor)m.instanceColor.needsUpdate=true;}}
 diagnostics(){return{beamSegments:this.beam.count,colors:7,sparks:this.sparks.count,rings:this.rings.count,draws:[this.beam,this.glow,this.rings,this.sparks].filter(m=>m.count>0).length};}
}
